{
  "version": "Notebook/1.0",
  "items": [
    {
      "type": 1,
      "content": {
        "json": "# Azure VM previous-generation capacity readiness"
      },
      "name": "title"
    },
    {
      "type": 9,
      "content": {
        "version": "KqlParameterItem/1.0",
        "crossComponentResources": [
          "{Subscriptions}"
        ],
        "parameters": [
          {
            "id": "p-subs",
            "version": "KqlParameterItem/1.0",
            "name": "Subscriptions",
            "label": "Subscriptions",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "isRequired": true,
            "query": "resourcecontainers\n| where type =~ 'microsoft.resources/subscriptions'\n| where properties.state =~ 'Enabled'\n| project value = id, label = name, selected = true\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "value::all"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Subscriptions to scan for previous-generation VM exposure."
          },
          {
            "id": "p-rg",
            "version": "KqlParameterItem/1.0",
            "name": "ResourceGroups",
            "label": "Resource groups",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "resources\n| where type =~ 'microsoft.compute/virtualmachines'\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\n| summarize Resources = count() by resourceGroup\n| project value = resourceGroup, label = strcat(resourceGroup, ' (', Resources, ')'), selected = false\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscriptions}"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "selectAllValue": "*",
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Limit results to selected resource groups."
          },
          {
            "id": "p-regions",
            "version": "KqlParameterItem/1.0",
            "name": "Regions",
            "label": "Regions",
            "type": 2,
            "multiSelect": true,
            "quote": "'",
            "delimiter": ",",
            "query": "resources\n| where type =~ 'microsoft.compute/virtualmachines'\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\n| summarize Resources = count() by location\n| project value = location, label = strcat(location, ' (', Resources, ')'), selected = false\n| order by label asc",
            "queryType": 1,
            "resourceType": "microsoft.resourcegraph/resources",
            "crossComponentResources": [
              "{Subscriptions}"
            ],
            "typeSettings": {
              "additionalResourceOptions": [
                "value::all"
              ],
              "selectAllValue": "*",
              "showDefault": false
            },
            "timeContext": {
              "durationMs": 86400000
            },
            "value": [
              "value::all"
            ],
            "description": "Limit results to selected Azure regions."
          },
          {
            "id": "p-inventory-query",
            "version": "KqlParameterItem/1.0",
            "name": "ComputeInventoryQuery",
            "type": 1,
            "value": "resources\r\n| where type =~ 'microsoft.compute/virtualmachines'\r\n    or type =~ 'microsoft.compute/virtualmachinescalesets'\r\n| extend\r\n    ResourceKind = iff(type =~ 'microsoft.compute/virtualmachines', 'VM', 'VMSS'),\r\n    TargetId = tolower(id),\r\n    VmSize = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.hardwareProfile.vmSize), tostring(sku.name)),\r\n    CurrentCapacity = iff(type =~ 'microsoft.compute/virtualmachines', 1, coalesce(toint(sku.capacity), 0)),\r\n    OperatingSystem = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.osType), ''),\r\n    Priority = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.priority), ''),\r\n    AvailabilitySet = iff(type =~ 'microsoft.compute/virtualmachines', extract('/availabilitySets/([^/]+)$', 1, tostring(properties.availabilitySet.id)), ''),\r\n    EphemeralOS = iff(type =~ 'microsoft.compute/virtualmachines', tostring(properties.storageProfile.osDisk.diffDiskSettings.option) =~ 'Local', false),\r\n    OrchestrationMode = tostring(properties.orchestrationMode),\r\n    UpgradeMode = tostring(properties.upgradePolicy.mode),\r\n    Zones = strcat_array(zones, ', ')\r\n| extend _sizeKey = toupper(VmSize), _loc = tolower(location)\r\n| extend Series = case(\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+S_V2$', 'Fsv2',\r\n    _sizeKey matches regex '^STANDARD_FS[0-9]+_V2$', 'Fsv2',\r\n    _sizeKey matches regex '^STANDARD_FS[0-9]+$', 'Fs',\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+[A-Z]*S$', 'Fs',\r\n    _sizeKey matches regex '^STANDARD_F[0-9]+$', 'F',\r\n\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V3$', 'Dsv3',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V3$', 'Dv3',\r\n    _sizeKey matches regex '^STANDARD_DS[0-9]+(-[0-9]+)?_V2$', 'Dsv2',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?S_V2$', 'Dsv2',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+I?_V2$', 'Dv2',\r\n    _sizeKey matches regex '^STANDARD_DS[0-9]+(-[0-9]+)?$', 'Ds',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+S$', 'Ds',\r\n    _sizeKey matches regex '^STANDARD_D[0-9]+$', 'D',\r\n\r\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*S$', 'Bs',\r\n    _sizeKey matches regex '^STANDARD_B[0-9]+[A-Z]*$', 'B',\r\n    _sizeKey matches regex '^STANDARD_A[0-9]+M_V2$', 'Amv2',\r\n    _sizeKey matches regex '^STANDARD_A[0-9]+_V2$', 'Av2',\r\n\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+(-[0-9]+)?I?S_V3$', 'Esv3',\r\n    _sizeKey matches regex '^STANDARD_E[0-9]+I?_V3$', 'Ev3',\r\n\r\n    _sizeKey matches regex '^STANDARD_GS[0-9]+(-[0-9]+)?$', 'Gs',\r\n    _sizeKey matches regex '^STANDARD_G[0-9]+S$', 'Gs',\r\n    _sizeKey matches regex '^STANDARD_G[0-9]+$', 'G',\r\n    _sizeKey matches regex '^STANDARD_L[0-9]+S_V2$', 'Lsv2',\r\n    _sizeKey matches regex '^STANDARD_L[0-9]+S$', 'Ls',\r\n    '')\r\n| extend Category = case(\r\n    Series in ('F','Fs','Fsv2'), 'Compute optimized',\r\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3','B','Bs','Av2','Amv2'), 'General purpose',\r\n    Series in ('Ev3','Esv3','G','Gs'), 'Memory optimized',\r\n    Series in ('Ls','Lsv2'), 'Storage optimized',\r\n    '')\r\n| extend\r\n    _sovereign = _loc matches regex '^(usgov|usdod|usnat|ussec|china)',\r\n    _npHc = _sizeKey matches regex '^STANDARD_(NP[0-9]+S|HC[0-9]+(-[0-9]+)?RS)$',\r\n    _v7Excluded = _sizeKey matches regex '^STANDARD_(D[0-9]+I?(S|DS|LS|LDS)|E[0-9]+(-[0-9]+)?I?(S|DS))_V7$',\r\n    _regionalPct = case(\r\n        _loc == 'northeurope', 17,\r\n        _loc in ('francecentral','francesouth'), 11,\r\n        _loc in ('westeurope','norwayeast','norwaywest'), 9,\r\n        _loc == 'southeastasia', 8,\r\n        0)\r\n| extend _v1v2 = _npHc or Series in ('D','Ds','Dv2','Dsv2','Ls','Av2','Amv2','B','Bs','F','Fs','Fsv2','G','Gs','Lsv2')\r\n| extend RetirementDate = case(\r\n    Series in ('D','Ds','Dv2','Dsv2','Ls'), datetime(2028-05-01),\r\n    Series in ('Av2','Amv2','B','Bs','F','Fs','Fsv2','G','Gs','Lsv2'), datetime(2028-11-15),\r\n    Series in ('Dv3','Dsv3','Ev3','Esv3') and not(_sovereign), datetime(2029-11-15),\r\n    _npHc, datetime(2027-05-31),\r\n    todatetime(''))\r\n| extend LifecycleStatus = case(\r\n    isempty(Series), '',\r\n    isnotnull(RetirementDate), 'Capacity restricted + retirement scheduled',\r\n    'Capacity restricted; product active')\r\n| extend RecommendedTarget = case(\r\n    Series in ('D','Ds','Dv2','Dsv2','Dv3','Dsv3'), 'Dv5/Dsv5, Dv6/Dsv6, or Dv7/Dsv7',\r\n    Series in ('Ev3','Esv3'), 'Ev5/Esv5, Esv6, or Esv7',\r\n    Series in ('Av2','Amv2'), 'Bsv2/Basv2 or D/E v5-v6',\r\n    Series in ('B','Bs'), 'Bsv2/Basv2 or Dlsv5-v6',\r\n    Series in ('F','Fs','Fsv2'), 'Dlsv5-v6, Dsv5, or Falsv6',\r\n    Series in ('G','Gs'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\r\n    Series in ('Ls','Lsv2'), 'Lsv3/Lasv3 or Lsv4/Lasv4',\r\n    '')\r\n| extend PriceChangePct = case(isempty(_sizeKey) or _sovereign, 0, _v1v2, 25, _v7Excluded, 0, _regionalPct)\r\n| extend PriceChange = case(\r\n    isempty(_sizeKey), 'Unknown size',\r\n    _sovereign, 'None (sovereign cloud)',\r\n    _v1v2, '+25% (v1/v2 series)',\r\n    _regionalPct > 0 and _v7Excluded, 'None (excluded v7 series)',\r\n    _regionalPct > 0, strcat('+', tostring(_regionalPct), '% regional'),\r\n    'None announced')\r\n| extend SizeVersion = iff(_sizeKey matches regex '_V[0-9]+$', strcat('v', extract('_V([0-9]+)$', 1, _sizeKey)), 'v1')\r\n| project-away _sizeKey, _loc, _sovereign, _npHc, _v7Excluded, _regionalPct, _v1v2\r\n| join kind=leftouter (\r\n    resources\r\n    | where type =~ 'microsoft.insights/autoscalesettings'\r\n    | mv-expand Profile = properties.profiles\r\n    | extend\r\n        TargetId = tolower(tostring(properties.targetResourceUri)),\r\n        ProfileMin = toint(Profile.capacity.minimum),\r\n        ProfileMax = toint(Profile.capacity.maximum)\r\n    | summarize AutoscaleMin = min(ProfileMin), AutoscaleMax = max(ProfileMax), AutoscaleProfiles = count() by TargetId\r\n  ) on TargetId\r\n| extend\r\n    AutoscaleMin = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMin, CurrentCapacity)),\r\n    AutoscaleMax = iff(ResourceKind == 'VM', 1, coalesce(AutoscaleMax, CurrentCapacity))\r\n| extend GrowthGap = iff(isnotempty(Series) and AutoscaleMax > CurrentCapacity, AutoscaleMax - CurrentCapacity, 0)\r\n| join kind=leftouter (\r\n    resourcecontainers\r\n    | where type =~ 'microsoft.resources/subscriptions'\r\n    | project subscriptionId, Subscription = name\r\n  ) on subscriptionId\r\n| extend\r\n    InstanceCount = CurrentCapacity,\r\n    Risk = case(isempty(Series), '', ResourceKind == 'VMSS' and GrowthGap > 0, 'Critical', RetirementDate < datetime(2029-01-01), 'High', 'Medium'),\r\n    MigrationConsiderations = strcat_array(array_concat(\r\n        iff(ResourceKind == 'VM' and isnotempty(AvailabilitySet), pack_array('Coordinate availability-set migration'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and isnotempty(Zones), pack_array('Validate target size in current zone'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and EphemeralOS, pack_array('Ephemeral OS disk - plan redeployment'), dynamic([])),\r\n        iff(ResourceKind == 'VM' and Priority =~ 'Spot', pack_array('Spot workload - validate replacement capacity'), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and GrowthGap > 0, pack_array(strcat('Autoscale growth gap: ', tostring(GrowthGap))), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and isnotempty(Zones), pack_array('Validate target size in every configured zone'), dynamic([])),\r\n        iff(ResourceKind == 'VMSS' and OrchestrationMode =~ 'Uniform', pack_array('Coordinate model and instance upgrade'), dynamic([]))\r\n      ), ' | '),\r\n    RiskRank = case(isempty(Series), 3, ResourceKind == 'VMSS' and GrowthGap > 0, 0, RetirementDate < datetime(2029-01-01), 1, 2),\r\n    Resource = name,\r\n    Location = location,\r\n    ResourceId = id,\r\n    ResourceGroup = resourceGroup,\r\n    SubscriptionId = subscriptionId",
            "isHiddenWhenLocked": true,
            "typeSettings": {
              "multiLineText": true,
              "editorLanguage": "text"
            },
            "description": "Shared VM and VMSS inventory query used by workbook visualizations."
          }
        ],
        "style": "pills",
        "queryType": 1,
        "resourceType": "microsoft.resourcegraph/resources"
      },
      "name": "parameters"
    },
    {
      "type": 11,
      "content": {
        "version": "LinkItem/1.0",
        "style": "tabs",
        "links": [
          {
            "id": "t1",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "Overview",
            "subTarget": "overview",
            "style": "link"
          },
          {
            "id": "t8",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "Price changes (Feb 2027)",
            "subTarget": "pricing",
            "style": "link"
          },
          {
            "id": "t2",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "Impacted VMs",
            "subTarget": "vms",
            "style": "link"
          },
          {
            "id": "t3",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "VMSS and autoscale",
            "subTarget": "vmss",
            "style": "link"
          },
          {
            "id": "t4",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "Migration plan",
            "subTarget": "migration",
            "style": "link"
          },
          {
            "id": "t5",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "VM SKU retirements",
            "subTarget": "vmRetirements",
            "style": "link"
          },
          {
            "id": "t6",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "Service Health and guidance",
            "subTarget": "guidance",
            "style": "link"
          },
          {
            "id": "t7",
            "cellValue": "selectedTab",
            "linkTarget": "parameter",
            "linkLabel": "About the data",
            "subTarget": "about",
            "style": "link"
          }
        ]
      },
      "name": "tabs"
    },
    {
      "type": 12,
      "content": {
        "version": "NotebookGroup/1.0",
        "groupType": "editable",
        "items": [
          {
            "type": 1,
            "content": {
              "json": "Existing VMs keep running, but no new quota is approved for these series. v1/v2 retire in 2028; Dv3, Dsv3, Ev3 and Esv3 on 15 Nov 2029. v4 is no longer restricted.",
              "style": "warning"
            },
            "name": "ovHeader"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| extend _affected = isnotempty(Series)\n| summarize\n    AffectedInstances = sumif(InstanceCount, _affected),\n    StandaloneVMs = countif(_affected and ResourceKind == 'VM'),\n    ScaleSets = countif(_affected and ResourceKind == 'VMSS'),\n    GrowthAtRisk = sum(GrowthGap),\n    V1V2Increase = sumif(InstanceCount, PriceChangePct == 25),\n    RegionalIncrease = sumif(InstanceCount, PriceChangePct > 0 and PriceChangePct < 25),\n    V3Retiring = sumif(InstanceCount, Series in ('Dv3','Dsv3','Ev3','Esv3')),\n    AffectedSubscriptions = dcountif(SubscriptionId, _affected),\n    Regions = dcountif(Location, _affected)\n| extend MetricRows = pack_array(\n    strcat('1|Affected VM instances|', tostring(AffectedInstances)),\n    strcat('2|Standalone VMs|', tostring(StandaloneVMs)),\n    strcat('3|VM scale sets|', tostring(ScaleSets)),\n    strcat('4|Autoscale growth at risk|', tostring(GrowthAtRisk)),\n    strcat('5|v1/v2 instances (+25%)|', tostring(V1V2Increase)),\n    strcat('6|Regional increase instances|', tostring(RegionalIncrease)),\n    strcat('7|v3 instances (retire 2029)|', tostring(V3Retiring)),\n    strcat('8|Affected subscriptions|', tostring(AffectedSubscriptions)),\n    strcat('9|Affected regions|', tostring(Regions))\n  )\n| mv-expand MetricRow = MetricRows to typeof(string)\n| extend MetricParts = split(MetricRow, '|')\n| project\n    Rank = toint(MetricParts[0]),\n    Metric = tostring(MetricParts[1]),\n    Value = tolong(MetricParts[2])\n| order by Rank asc",
              "size": 3,
              "title": "Capacity exposure summary",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "tiles",
              "tileSettings": {
                "titleContent": {
                  "columnMatch": "Metric",
                  "formatter": 1
                },
                "leftContent": {
                  "columnMatch": "Value",
                  "formatter": 12,
                  "formatOptions": {
                    "palette": "auto"
                  },
                  "numberFormat": {
                    "unit": 17,
                    "options": {
                      "style": "decimal",
                      "maximumFractionDigits": 0
                    }
                  }
                },
                "showBorder": true,
                "sortCriteriaField": "Rank",
                "sortOrderField": 1
              }
            },
            "name": "Capacityexposuresummary"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| where isnotempty(Series)\n| summarize Instances = sum(InstanceCount) by Series\n| order by Instances desc",
              "size": 1,
              "title": "Affected instances by series",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "barchart"
            },
            "name": "Affectedinstancesbyseries"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| where isnotempty(Series)\n| summarize Instances = sum(InstanceCount) by Region = Location\n| order by Instances desc",
              "size": 1,
              "title": "Affected instances by region",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "barchart"
            },
            "name": "Affectedinstancesbyregion"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| where isnotempty(Series)\n| summarize Resources = count() by Risk\n| extend RiskRank = case(Risk == 'Critical', 0, Risk == 'High', 1, Risk == 'Medium', 2, 3)\n| order by RiskRank asc\n| project-away RiskRank",
              "size": 1,
              "title": "Resources by risk",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "visualization": "piechart"
            },
            "name": "Resourcesbyrisk"
          },
          {
            "type": 3,
            "content": {
              "version": "KqlItem/1.0",
              "query": "{ComputeInventoryQuery}\n| extend _rgs = dynamic([{ResourceGroups}])\n| where array_length(_rgs) == 0 or set_has_element(_rgs, '*') or set_has_element(_rgs, resourceGroup)\n| extend _regions = dynamic([{Regions}])\n| where array_length(_regions) == 0 or set_has_element(_regions, '*') or set_has_element(_regions, location)\n| where isnotempty(Series)\n| project\n    Resource,\n    Risk,\n    ['Capacity / lifecycle'] = LifecycleStatus,\n    ['Feb 2027 price change'] = PriceChange,\n    Type = ResourceKind,\n    Subscription,\n    ['Resource group'] = ResourceGroup,\n    Region = Location,\n    ['VM size'] = VmSize,\n    Series,\n    ['Instances'] = InstanceCount,\n    ['Growth at risk'] = GrowthGap,\n    ['Retirement date'] = RetirementDate,\n    ['Target family guidance'] = RecommendedTarget,\n    ResourceId,\n    RiskRank\n| order by ['Instances'] desc, RiskRank asc, ['Growth at risk'] desc, Resource asc\n| project-away RiskRank",
              "size": 2,
              "title": "All impacted VMs and scale sets",
              "queryType": 1,
              "resourceType": "microsoft.resourcegraph/resources",
              "crossComponentResources": [
                "{Subscriptions}"
              ],
              "showExportToExcel": true,
              "gridSettings": {
                "rowLimit": 1000,
                "filter": true,
                "formatters": [
                  {
                    "columnMatch": "Risk",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "Critical",
                          "representation": "redBright",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "==",
                          "thresholdValue": "High",
                          "representation": "red",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "==",
                          "thresholdValue": "Medium",
                          "representation": "orange",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "Default",
                          "representation": "gray",
                          "text": "{0}{1}"
                        }
                      ]
                    }
                  },
                  {
                    "columnMatch": "Growth at risk",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "==",
                          "thresholdValue": "0",
                          "representation": "green",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": ">",
                          "thresholdValue": "0",
                          "representation": "redBright",
                          "text": "{0}{1}"
                        },
                        {
                          "operator": "Default",
                          "representation": "gray",
                          "text": "{0}{1}"
                        }
                      ]
                    },
                    "numberFormat": {
                      "unit": 0,
                      "options": {
                        "style": "decimal",
                        "maximumFractionDigits": 0
                      },
                      "emptyValCustomText": "0"
                    }
                  },
                  {
                    "columnMatch": "Retirement date",
                    "formatter": 6,
                    "formatOptions": {
                      "customColumnWidthSetting": "18ch"
                    },
                    "dateFormat": {
                      "showUtcTime": true,
                      "formatName": "shortDatePattern"
                    }
                  },
                  {
                    "columnMatch": "ResourceId",
                    "formatter": 13,
                    "formatOptions": {
                      "linkColumn": "ResourceId",
                      "linkTarget": "Resource",
                      "linkIsContextBlade": true,
                      "showIcon": true,
                      "customColumnWidthSetting": "32ch"
                    }
                  },
                  {
                    "columnMatch": "Feb 2027 price change",
                    "formatter": 18,
                    "formatOptions": {
                      "thresholdsOptions": "colors",
                      "thresholdsGrid": [
                        {
                          "operator": "contains",
