              "query": "servicehealthresources\n| where type =~ 'microsoft.resourcehealth/events'\n| extend\n    EventType = tostring(properties.EventType),\n    EventSubType = tostring(properties.EventSubType),\n    Status = tostring(properties.Status),\n    Title = tostring(properties.Title),\n    TrackingId = tostring(properties.TrackingId),\n    SummaryHtml = tostring(properties.Summary),\n    EventDate = todatetime(tolong(properties.ImpactMitigationTime))\n| where EventType == 'HealthAdvisory'\n| extend NoticeText = tolower(strcat(Title, ' ', SummaryHtml))\n| where NoticeText contains 'previous-generation'\n    or NoticeText contains 'previous generation'\n    or NoticeText contains 'capacity growth restriction'\n    or NoticeText contains 'v1-v4'\n    or NoticeText contains 'dsv3'\n    or NoticeText contains 'esv3'\n    or (NoticeText contains 'virtual machine' and (NoticeText contains 'end of life' or NoticeText contains 'pric'))\n| extend Summary = trim(' ', replace_regex(SummaryHtml, '<[^>]+>', ' '))\n| project\n    ['Tracking ID'] = TrackingId,\n    Subscription = subscriptionId,\n    Status,\n    Title,\n    Summary,\n    ['Advisory date'] = EventDate\n| order by ['Advisory date'] desc",
